-- 012-umra-tours.sql
-- Умра как бронируемые туры: 9 программ = 9 туров под направлением «Умра»,
-- заезды по явным датам, цены за человека по типу номера QUAD/TRPL/DBL
-- (детских тарифов нет). Данные реальные, из курируемого списка оператора
-- (tools/build-seed.py → UMRA_PROGRAMS). Осенние «еженедельные» даты пока не
-- заводятся — добавим точным списком, когда оператор пришлёт числа.
--
-- Идемпотентна: сначала удаляет всё по направлению «Умра», потом вставляет
-- заново. Заезды/цены/агентства Карадениза и брони по нему НЕ трогает.
-- ВНИМАНИЕ: удаляет заезды Умры — если по ним УЖЕ есть брони, повторный
-- прогон их осиротит. На момент первого добавления броней по Умре нет.
--
-- Прогон (оператор, wrangler залогинен):
--   cd worker
--   wrangler d1 execute turon-tour --remote --file=../db/migrations/012-umra-tours.sql

DELETE FROM departure_prices WHERE departure_id IN (
  SELECT d.id FROM departures d JOIN tours t ON t.id = d.tour_id WHERE t.destination = 'Умра');
DELETE FROM departures WHERE tour_id IN (SELECT id FROM tours WHERE destination = 'Умра');
DELETE FROM tour_content WHERE tour_id IN (SELECT id FROM tours WHERE destination = 'Умра');
DELETE FROM tours WHERE destination = 'Умра';
DELETE FROM destinations WHERE name = 'Умра';

